BK({ id: 'feueratem', n: 'Feueratem', k: 'atem', lv: 3, man: true, t: 'energie kraft', st: 'kund', src: 'Modul 2, S. 56', d: 'Beim Ausatmen den Bauch bzw. Nabel einziehen, beim Einatmen weitet er sich; der Atem kann recht schnell ausgeführt werden (Shakti Naam / Kundalini).', w: 'Im Skript als Naam-Yoga-Technik beschrieben; auf das eigene Befinden achten.', txt: 'Atme rhythmisch durch die Nase: Beim Ausatmen den Nabel zur Wirbelsäule ziehen, beim Einatmen löst sich der Bauch von selbst. Nur so lange, wie es angenehm ist.' });
BK({ id: 'langer_atem', n: 'Langer tiefer Atem', k: 'atem', t: 'atem ruhe', st: 'kund', src: 'Modul 2, S. 57–58', d: 'Nutzt die gesamte Lungenkapazität (anders als der Feueratem): Einatmen in Bauch, Brustraum und oberen Brustbereich, Ausatmen mit eingezogenem Nabel und Zwerchfell.', txt: 'Atme tief und langsam ein: Bauch, mittlerer, dann oberer Brustraum. Beim Ausatmen Nabel und Zwerchfell zur Wirbelsäule ziehen, bis die Lungen entleert sind. Wirbelsäule aufrecht.' });
BK({ id: 'dreipunkt_atem', n: '3-Punkte-Atem', k: 'atem', lv: 2, t: 'balance ruhe', st: 'kund', src: 'Modul 2, S. 60', d: 'Einatmen, Halten und Ausatmen in gleich langen Teilen durch die Nase; Zeiten lassen sich steigern bis zu einem Atemzyklus von einer Minute.', txt: 'Atme durch die Nase ein, halte den Atem und atme aus – alle drei Teile gleich lang. Steigere die Zeiten nur langsam und nur so weit, wie es angenehm ist.' });
BK({ id: 'wechselatmung', n: 'Wechselatmung', k: 'atem', lv: 2, sa: 'Nadi Shodhana', t: 'balance ruhe', st: 'hatha', src: 'Modul 5, S. 62–65', d: 'Grundübung des Yoga: wirkt beruhigend bei Stress und belebend bei Müdigkeit; abwechselnd durch das linke und rechte Nasenloch atmen, 4–8 Runden, Vishnu Mudra.', txt: 'Rechte Hand im Vishnu Mudra. Links einatmen, beide Nasenlöcher schließen, rechts ausatmen; rechts einatmen, schließen, links ausatmen. 4–8 Runden, ruhig und ohne Anstrengung.' });
BK({ id: 'chakra_atem', n: 'Chakra-Atem (Quelle des Lichts)', k: 'atem', t: 'ruhe licht wurzel herz', st: 'kund', src: 'Modul 6, S. 46–48', d: 'Atem mit Vorstellung von Licht, das durch die Chakren fließt; bringt den Körper zur Ruhe und eignet sich als Einstimmung. Im Skript mit Wirkungen auf die einzelnen Chakren beschrieben.', txt: 'Sitze aufrecht, Hände in Gyan Mudra oder vor dem Herzen. Atme Licht vom Scheitel bis zum Wurzelchakra ein und stelle dir vor, wie es sich im ganzen Körper ausbreitet.' });
BK({ id: 'kuehlende_atmung', n: 'Kühlende Atmung', k: 'atem', lv: 2, sa: 'Sitali', t: 'ruhe', st: 'kund hatha', sv: true, src: 'Modul 6, S. 49', d: 'Zunge zu einem Röhrchen rollen, kühle Luft einatmen, Zunge zurückziehen und durch die Nase ausatmen.', txt: 'Rolle die Zunge zu einem Röhrchen, atme die kühle Luft ein, ziehe die Zunge zurück und atme durch die Nase aus.' });
BK({ id: 'ujjayi', n: 'Meeresrauschen-Atem', k: 'atem', lv: 2, sa: 'Ujjayi', t: 'ruhe kraft', st: 'hatha kund', src: 'Modul 6, S. 50–53', d: 'Atmung mit leicht verengter Stimmritze und sanftem Rauschen; kann mit Asanas kombiniert werden. Im Skript: trägt zu einem meditativen Zustand bei, günstig bei Asthma und Bluthochdruck.', w: 'Kontraindikation laut Skript: niedriger Blutdruck, starke Introvertiertheit.', txt: 'Verenge beim Atmen die Stimmritze leicht, sodass ein weiches Rauschen wie Meeresrauschen entsteht. Gleichmäßig ein, gleichmäßig aus.' });
BK({ id: 'pranischer_atem', n: 'Pranischer Atem im Stehen', k: 'atem', man: true, t: 'energie kraft wurzel', st: 'kund', src: 'Modul 6, S. 54–56; Modul 8, S. 50–55', d: 'Atemübungen im Stehen mit verschiedenen Handpositionen (z. B. zur Entwicklung von Willens- und Gedächtniskraft); aufrechter Stand, Bracing, Lächeln.', txt: 'Stehe aufrecht, Füße zusammen, Hände wie in der gewählten Position. Atme rhythmisch und bewusst, Kopf gerade, Augen geöffnet.' });
BK({ id: 'king_kong', n: 'King Kong', k: 'atem', man: true, t: 'energie', st: 'kund', src: 'Modul 8, S. 56–57', d: 'Schwungvolle Atemübung im Stehen: Arme als V über den Kopf, in die Hände klatschen, mit „Haaa“ ausatmen. Wirkung laut Skript: stärkt das Immunsystem, weckt die Lebensenergie, fördert die Durchblutung.', txt: 'Stehe schulterbreit, atme ein und führe die Arme über dem Kopf zu einem V. Klatsche zweimal in die Hände und atme mit einem „Haaa“ kraftvoll aus.' });
